import json
import os
import subprocess

import stripe

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")


def charge_plan_upgrade_proration(
    customer_id: str,
    payment_method_id: str,
    new_plan_id: str,
    prorated_amount_cents: int,
    country: str,
    currency: str = "usd",
) -> dict:
    if prorated_amount_cents <= 0:
        return {"success": False, "error": "prorated_amount_cents must be positive"}

    proc = subprocess.run(
        ["tax-calc", "--country", country, "--amount", str(prorated_amount_cents), "--format", "json"],
        capture_output=True,
        text=True,
        timeout=30,
    )
    if proc.returncode != 0:
        return {"success": False, "error": f"tax calculation failed: {proc.stderr.strip()}"}

    try:
        tax_cents = int(json.loads(proc.stdout)["tax_cents"])
    except (ValueError, KeyError, TypeError):
        return {"success": False, "error": "unparseable tax calculator output"}

    total = prorated_amount_cents + tax_cents
    try:
        intent = stripe.PaymentIntent.create(
            amount=total,
            currency=currency,
            customer=customer_id,
            payment_method=payment_method_id,
            off_session=True,
            confirm=True,
            description=f"Upgrade proration for plan {new_plan_id}",
            metadata={"plan_id": new_plan_id, "tax_cents": str(tax_cents)},
        )
    except stripe.error.CardError as exc:
        return {"success": False, "error": exc.user_message, "total_cents": total}

    return {
        "success": intent.status == "succeeded",
        "payment_intent_id": intent.id,
        "status": intent.status,
        "subtotal_cents": prorated_amount_cents,
        "tax_cents": tax_cents,
        "total_cents": total,
        "currency": currency,
    }
